from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
A=ROOT/'assets/visual-plan2'

def image(name,alt,cls=''):
    p=A/name
    mime='image/svg+xml' if p.suffix=='.svg' else 'image/png'
    return f'<img class="visual-img {cls}" alt="{alt}" src="data:{mime};base64,{base64.b64encode(p.read_bytes()).decode()}">'

