def icon(kind,cls=''):
    return f'<svg class="vicon {cls}" viewBox="0 0 128 128" aria-hidden="true"><g fill="var(--icon-fill,#e4f2f9)" stroke="var(--icon-stroke,#05507d)" stroke-width="5" stroke-linecap="round" stroke-linejoin="round">{paths[kind]}</g></svg>'
def svg(content,view='0 0 800 420',cls=''):
    return f'<svg class="scene-diagram {cls}" viewBox="{view}" role="img" aria-label="개념 관계도">{content}</svg>'
def node(kind,x,y,label,sub='',size=115):
    return f'<g transform="translate({x} {y})"><svg width="{size}" height="{size}" viewBox="0 0 128 128"><g fill="#e4f2f9" stroke="#05507d" stroke-width="4" stroke-linecap="round" stroke-linejoin="round">{paths[kind]}</g></svg><text x="{size/2}" y="{size+34}" text-anchor="middle" class="svg-label">{label}</text><text x="{size/2}" y="{size+65}" text-anchor="middle" class="svg-small">{sub}</text></g>'
def arrow(x1,y1,x2,y2):
    # One visible connection, with its arrowhead part of the same path.
    return f'<path d="M{x1} {y1}L{x2} {y2}m-10-7 10 7-10 7" class="route-line"/><circle r="5" fill="#00a5e5" class="route-packet"><animateMotion dur="2.6s" repeatCount="indefinite" path="M{x1} {y1}L{x2-12} {y2}"/></circle>'
def trio(items):
    return '<div class="visual-trio">'+''.join(f'<div>{icon(k)}<h3>{t}</h3><p>{d}</p></div>' for k,t,d in items)+'</div>'
def caption(t,d):return f'<div class="scene-caption"><b>{t}</b><p>{d}</p></div>'
def scene_side(art,explanation,cls=''):
    return f'<div class="scene-side {cls}"><div class="scene-art">{art}</div><div class="scene-text">{explanation}</div></div>'

