    slides[14]['body']=scene_side('<div class="model-console"><div class="console-title">같은 업무로 비교하기</div>'+''.join(f'<div class="console-row"><span>{t}</span><div><i style="left:{v}%"></i></div><b>{s}</b></div>' for t,v,s in [('난도',65,'작은 변경 ↔ 원인 분석'),('응답 속도',30,'얼마나 기다릴 수 있나'),('비용',48,'결과와 사용량 함께 보기')])+'<p>수치는 성능 측정값이 아닌 비교 관점의 그림입니다.</p></div>',caption('기본값에서 작게 시작','간단한 변경과 여러 파일의 오류 분석은 필요한 검토 깊이가 다릅니다.')+caption('추론 노력 = 검토에 쓰는 자원','더 많은 시간·사용량을 쓸 수 있지만 정확성을 보장하지는 않습니다.')+caption('설정도 질문할 수 있습니다','“이 작업에 적합한 모델과 설정을 이유와 함께 설명해줘.”'))
    slides[15]['body']=scene_side('<div class="build-stage"><div class="build-step">'+icon('file')+'<span class="build-label">업무 메모</span></div><span class="build-connector" aria-hidden="true">→</span><div class="build-step">'+icon('robot')+'<span class="build-label">에이전트와 제작</span></div><span class="build-connector" aria-hidden="true">→</span><div class="build-step">'+icon('browser')+'<span class="build-label">나의 작은 도구</span></div></div>','<div class="request-quote"><span class="micro">첫 요청</span><blockquote>업무 요청을 붙여 넣으면<br>담당자, 할 일, 기한을 정리해 주는<br>간단한 도구를 만들어줘.</blockquote><p>외부 API 없이 첫 버전을 만듭니다.<br>실행 가능한 흐름부터 만들고 고칩니다.</p></div>')
    slides[16]['body']=slides[16]['body'].replace('<div class="ide-top">','<div class="ide-top">'+image('vscode.png','Visual Studio Code 공식 아이콘','ide-logo'),1)
    slides[17]['body']='<div class="mini-process">'+icon('file')+'<span>업무 요청</span><i>→</i>'+icon('gear')+'<span>규칙으로 읽기</span><i>→</i>'+icon('check')+'<span>결과 확인</span></div>'+slides[17]['body']
    slides[18]['body']=slides[18]['body'].replace('<span class="micro">입력</span>',icon('calendar','revision-calendar')+'<span class="micro">입력</span>')
    slides[19]['body']=slides[19]['body'].replace('<div class="codebox">','<div class="codebox rules-book">'+icon('book','book-cover'),1)
    slides[20]['body']='<div class="loop-visual">'+svg('<path d="M240 90H600Q710 90 710 210T600 330H240Q130 330 130 210T240 90" class="route-line" fill="none"/>'+node('chat',155,25,'요청')+node('gear',555,25,'실행')+node('check',555,255,'확인')+node('file',155,255,'수정')+'<text x="435" y="230" text-anchor="middle" class="svg-core">결과가 다음 요청의 근거</text>','0 0 880 485')+'<div class="loop-copy"><h3>짧게 만들고,<br>실제로 확인합니다.</h3><p>“기한이 없을 때 빈칸입니다.<br>확인 필요로 표시해줘.”</p><small>정상 입력과 예외 입력을 함께 확인합니다.</small></div></div>'
    slides[20]['theme']='visual-loop'
    slides[21]['body']=slides[21]['body'].replace('<div class="window-icon">AI</div>',icon('robot','tool-picture')).replace('<div class="window-icon">&lt; / &gt;</div>',image('vscode.png','Visual Studio Code 공식 아이콘','tool-picture')).replace('<div class="window-icon">&gt;_</div>',icon('terminal','tool-picture'))
    # Software identity icons are embedded without recoloring or distortion.
    slides[22]['body']=slides[22]['body'].replace('<div id="setup-equipment" class="equipment"></div>','<div id="setup-equipment" class="equipment"></div><template id="software-icons">'+icon('browser')+image('python.svg','Python 공식 로고')+image('nodejs.svg','Node.js 공식 로고')+image('git.svg','Git 공식 로고')+'</template>')
    slides[22]['body']+='<p class="asset-credit">Git logo: Jason Long · CC BY 3.0. 각 제품의 공식 식별 아이콘을 교육 목적으로 사용.</p>'
    slides[23]['body']=trio([('browser','HTML 파일','브라우저에서 열기. 단순 도구는 파일 하나로 사용할 수 있습니다.'),('gear','Python 프로그램','Python과 필요한 패키지를 준비하고 명령어로 실행합니다.'),('server','서버가 있는 웹 앱','서버를 실행하거나 배포합니다. 화면 파일만 옮겨서는 부족합니다.')])+'<div class="speech wide">“처음 받는 사람도 실행할 수 있도록 설치 항목과 실행 순서를 적어줘.”</div>'
    slides[24]['body']=scene_side('<div class="permission-territory"><div class="territory-ring outer"><span>외부 네트워크</span></div><div class="territory-ring inner"><span>프로젝트 폴더</span>'+icon('folder')+'</div><div class="gate">'+icon('lock')+'<b>행동 전 승인</b></div></div>',caption('접근 범위','어떤 파일·명령·네트워크를 사용할 수 있는가.')+caption('승인 방식','어떤 행동 전에 사용자 확인이 필요한가.')+caption('맡길 일에 맞게 설정','Full Access가 모든 작업의 필수 조건은 아닙니다. 회사에서 허용한 도구와 권한을 확인합니다.'))
    slides[25]['body']='<div class="visual-compare"><div><h3>AI로 만든 프로그램</h3>'+svg(node('robot',70,28,'개발할 때 AI')+arrow(225,95,345,95)+node('browser',385,28,'완성된 도구'),'0 0 650 255')+'<p>실행할 때는 정해진 코드가 처리합니다.<br>첫 예제는 모델을 호출하지 않습니다.</p></div><div><h3>AI를 부르는 프로그램</h3>'+svg(node('browser',70,28,'실행 중인 도구')+arrow(225,95,345,95)+node('cloud',385,28,'API로 AI 호출'),'0 0 650 255')+'<p>자유로운 문장을 AI에 보내 결과를 받습니다.<br>응답을 업무 기준으로 확인해야 합니다.</p></div></div>'
    slides[25]['theme']='visual-compare-ai'
    slides[26]['body']=slides[26]['body'].replace('<div class="api-route">','<div class="api-route pictorial-route">',1)
    for label,k in [('HTML 화면','browser'),('Python 백엔드','server'),('P-GPT API','cloud'),('화면 표시','check')]:
        slides[26]['body']=slides[26]['body'].replace('<b>'+label+'</b>',icon(k)+'<b>'+label+'</b>',1)
    slides[27]['body']=slides[27]['body'].replace('<h3>업무 요청 정리 도구</h3>',icon('browser','key-browser')+'<h3>업무 요청 정리 도구</h3>').replace('<h3>백엔드</h3>',icon('server','key-server')+'<h3>백엔드</h3>')
    slides[28]['body']=slides[28]['body'].replace('<span>01</span>',icon('check','ledger-icon')).replace('<span>02</span>',icon('key','ledger-icon')).replace('<span>03</span>',icon('plug','ledger-icon'))
    slides[29]['body']='<div class="network-roads"><div><span class="micro">경로 A · 서비스 안에서 검색</span>'+svg(node('browser',10,40,'프로그램')+arrow(140,98,205,98)+node('cloud',235,40,'P-GPT')+arrow(365,98,425,98)+node('search',455,40,'내장 검색'),'0 0 610 265')+'<p>P-GPT가 내장 검색을 제공하는지, 어떤 모델·도구에서 가능한지 확인합니다.</p></div><div><span class="micro">경로 B · 프로그램이 직접 접근</span>'+svg(node('browser',10,40,'프로그램')+arrow(140,98,205,98)+node('lock',235,40,'사내 연결 환경')+arrow(365,98,425,98)+node('network',455,40,'외부 웹'),'0 0 610 265')+'<p>네트워크 허용 범위와 필요한 인증서·프록시 설정을 확인합니다.</p></div></div><p class="bottom-note">접속·인증·인증서 오류는 원인이 다릅니다. 실제 오류와 발생 위치를 확인합니다.</p>'
    slides[30]['body']=slides[30]['body'].replace('<p>반복해서', '<p>'+icon('file')+'반복해서').replace('<p>결과가', '<p>'+icon('check')+'결과가').replace('<p>가상 자료', '<p>'+icon('gear')+'가상 자료')
    for s in slides:s['theme']+=' visual-edition'
    return slides
